contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, bool tryDeposit) public payable {
        require(amount <= address(this).balance);
        uint beforeBal = address(c).balance;
        uint beforeUserBal = c.balances(address(this));
        require(beforeBal == 0);

        if (tryDeposit && amount < c.MinDeposit()) {
            c.Deposit{value: amount}();
            assert(address(c).balance == beforeBal && c.balances(address(this)) == beforeUserBal);
        } else if (tryDeposit) {
            c.Deposit{value: amount}();
            assert(address(c).balance == beforeBal + amount && c.balances(address(this)) == beforeUserBal + amount);
        } else {
            assert(address(c).balance == beforeBal && c.balances(address(this)) == beforeUserBal);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount >= c.MinDeposit());
        require(address(this).balance >= amount);

        uint beforeUserBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        c.Deposit{value: amount}();

        uint afterUserBal = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        assert(afterUserBal == beforeUserBal + amount && afterContractBal == beforeContractBal + amount);
    }

    receive() external payable {}
